+
+function _Iso8601DecodeTime(P: PUtf8Char; L: PtrInt; var iso: TIsoTime): boolean;
+  {$ifdef HASINLINE}inline;{$endif}
+var
+  i: PtrInt;
+begin
+  result := false;
+  if P = nil then
+    exit;
+  if L = 0 then
+    while P[L] <> #0 do
+      inc(L);
+  i := 0;
